const fs = require('fs');
const path = require('path');
const AUDIT_LOG = path.join(__dirname, '..', 'logs', 'audit.jsonl');

function appendAudit(entry) {
  fs.appendFileSync(AUDIT_LOG, JSON.stringify(entry) + '\n');
}

function completePrimaryJob(jobId, result) {
  appendAudit({ jobId, event: 'completed', result });
  return { ok: true, jobId, result };
}

module.exports = { appendAudit, completePrimaryJob, AUDIT_LOG };

